def car_race_collision(n: int):
    positions = [0] * n
    speeds = [1] * n
    collisions = 0

    for i in range(n):
        for j in range(i+1, n):
            if (positions[j] - positions[i]) * (speeds[i] - speeds[j]) > 0:
                collisions += 1

    return collisions

